                mdBody += checkMd;
                fullLogContent += checkFull;
            } else {
                var reason = ghResult.reason || jenkinsResult.reason || 'unknown fetch failure';
                mdBody += '- ⚠️ **Log**: log fetch failed: ' + reason + '\n\n';
                fullLogContent += '=== LOG FETCH FAILED for: ' + check.name + ' ===\n' +
