        var fullLogWritten = false;
        try {
            file_write({ path: inputFolder + '/ci_failures_full.log', content: fullLogContent });
            fullLogWritten = true;
            console.log('✅ Wrote ci_failures_full.log');
        } catch (writeErr) {
            console.warn('Could not write ci_failures_full.log (non-fatal):',
