/** Concatenate the logs of a run's failed jobs, each under a `=== name ===` header. */
function formatFailedRunJobLogs(scm, owner, repo, rawJobs) {
    var out = '';
    ciModule._jobsOf(rawJobs).forEach(function (runJob) {
