       md += ghSections.md;
       full += ghSections.full;
   }
   if (jenkinsResult.logs) {
       var jenkinsSections = buildLogSections(check, jenkinsResult.logs, 'Jenkins error log');
       md += jenkinsSections.md;
       full += jenkinsSections.full;
   }
   if (full) return { md: md, full: full };

