function buildCheckLogSections(check, scm, owner, repo, jenkinsBasePath) {
   var ghResult = fetchGithubCheckLogsDetailed(check, scm, owner, repo);
   var jenkinsResult = fetchJenkinsCheckLogsDetailed(check, jenkinsBasePath);

