```javascript
function fetchGithubJobLogsDetailed(jobId, scm, owner, repo) {
   try {
       var logs = _fetchJobLogs(scm, owner, repo, jobId);
       if (logs) return { logs: logs };
       return { reason: 'job log for ' + jobId + ' came back empty' };
